import json
import os
import subprocess
import sys
from pathlib import Path
import tempfile
import unittest

ROOT_DIR = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
SCRIPT = os.path.join(ROOT_DIR, "src", "scripts", "check-voice-populated.py")

TEMPLATE_STUB = (
    "> Updated <YYYY-MM-DD> by <plugin>\n"
    "> Status: empty (run `/academic-writer:init` to seed Stage 1, then "
    "`/academic-writer:voice` for Stage 2)\n\n"
    "# Voice Profile — <writer name>\n\n"
    "## Core voice (cross-project)\n\n"
    "_Empty. Populated by Stage 1 miner and Stage 2 interview._\n\n"
    "## Terminology\n\n_Empty._\n\n"
    "## Academic-specific\n\n_Empty._\n\n"
    "## Non-fiction-book-specific\n\n_Empty._\n"
)

PARTIAL_REAL = (
    "> Updated 2026-08-07 by academic-writer\n\n"
    "# Voice Profile — Yotam Fromm\n\n"
    "## Core voice (cross-project)\n\n"
    "- Never open with a rhetorical question. Prefer a declarative claim in sentence one.\n"
    "- Em-dash for a hard pivot mid-sentence; semicolon only when both clauses could stand alone.\n\n"
    "## Terminology\n\n_Empty._\n\n"
    "## Academic-specific\n\n_Empty._\n\n"
    "## Non-fiction-book-specific\n\n_Empty._\n"
)

TINY_NOT_ENOUGH = (
    "> Updated 2026-08-07 by academic-writer\n\n"
    "# Voice Profile — Yotam Fromm\n\n"
    "## Core voice (cross-project)\n\nBe direct.\n\n"
    "## Terminology\n\n_Empty._\n\n"
    "## Academic-specific\n\n_Empty._\n\n"
    "## Non-fiction-book-specific\n\n_Empty._\n"
)


def run_script(*args):
    return subprocess.run(
        [sys.executable, SCRIPT, *args],
        capture_output=True,
        text=True,
        timeout=30,
    )


class TestCheckVoicePopulated(unittest.TestCase):
    def _write(self, tmpdir, content, name="AUTHOR_VOICE.md"):
        path = os.path.join(tmpdir, name)
        with open(path, "w", encoding="utf-8") as f:
            f.write(content)
        return path

    def test_missing_file_is_stub(self):
        proc = run_script(
            os.path.join(tempfile.gettempdir(), "does-not-exist-AUTHOR_VOICE.md")
        )
        self.assertEqual(proc.returncode, 1)
        self.assertIn("STUB", proc.stdout)

    def test_untouched_template_is_stub(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            path = self._write(tmpdir, TEMPLATE_STUB)
            proc = run_script(path, "--json")
            self.assertEqual(proc.returncode, 1)
            data = json.loads(proc.stdout)
            self.assertFalse(data["populated"])
            self.assertIn("placeholder_untouched", data["reasons"])
            self.assertIn("all_sections_empty", data["reasons"])
            self.assertEqual(data["populatedSections"], 0)

    def test_partial_real_profile_is_populated(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            path = self._write(tmpdir, PARTIAL_REAL)
            proc = run_script(path, "--json")
            self.assertEqual(proc.returncode, 0)
            data = json.loads(proc.stdout)
            self.assertTrue(data["populated"])
            self.assertEqual(data["reasons"], [])
            self.assertEqual(data["populatedSections"], 1)
            self.assertGreaterEqual(data["totalWords"], 20)

    def test_below_minimum_content_is_stub(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            path = self._write(tmpdir, TINY_NOT_ENOUGH)
            proc = run_script(path, "--json")
            self.assertEqual(proc.returncode, 1)
            data = json.loads(proc.stdout)
            self.assertFalse(data["populated"])
            self.assertIn("below_minimum_content", data["reasons"])
            self.assertEqual(data["populatedSections"], 1)

    def test_min_words_override(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            path = self._write(tmpdir, TINY_NOT_ENOUGH)
            proc = run_script(path, "--json", "--min-words", "2")
            self.assertEqual(proc.returncode, 0)
            data = json.loads(proc.stdout)
            self.assertTrue(data["populated"])

    def test_repo_root_author_voice_is_currently_a_stub(self):
        """Regression guard: the committed root AUTHOR_VOICE.md is the pipeline's own
        never-populated template and must be detected as a stub."""
        root_author_voice = os.path.join(ROOT_DIR, "AUTHOR_VOICE.md")
        proc = run_script(root_author_voice, "--json")
        self.assertEqual(proc.returncode, 1)
        data = json.loads(proc.stdout)
        self.assertFalse(data["populated"])

    def test_non_utf8_file_is_usage_error_not_stub(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            path = os.path.join(tmpdir, "AUTHOR_VOICE.md")
            with open(path, "wb") as f:
                f.write(b"\xff\xfe not valid utf-8 \x80")
            proc = run_script(path)
            self.assertEqual(proc.returncode, 2)

    def test_shared_voice_store_populated_without_project_file_passes(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            data_dir = Path(tmpdir) / "data"
            voice_dir = data_dir / "voice"
            voice_dir.mkdir(parents=True)
            (voice_dir / "profile.json").write_text(
                json.dumps({"schemaVersion": 1, "authorVoice": PARTIAL_REAL}),
                encoding="utf-8",
            )
            proc = run_script(
                str(Path(tmpdir) / "missing" / "AUTHOR_VOICE.md"),
                "--data-dir",
                str(data_dir),
                "--json",
            )
            self.assertEqual(proc.returncode, 0)
            data = json.loads(proc.stdout)
            self.assertTrue(data["populated"])
            self.assertEqual(data["source"], "voice_store.authorVoice")

    def test_neither_shared_store_nor_project_file_is_stub(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            data_dir = Path(tmpdir) / "data"
            (data_dir / "voice").mkdir(parents=True)
            proc = run_script(
                str(Path(tmpdir) / "missing" / "AUTHOR_VOICE.md"),
                "--data-dir",
                str(data_dir),
                "--json",
            )
            self.assertEqual(proc.returncode, 1)
            data = json.loads(proc.stdout)
            self.assertFalse(data["populated"])
            self.assertIn("missing", data["reasons"])


if __name__ == "__main__":
    unittest.main()
